contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 donateAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donateAmount)); require(donateAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= donateAmount);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        bool revertedSecond;
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedSecond = true; } else { revertedSecond = false; }

        bool revertedDonate;
        c.donate{value: donateAmount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedDonate = true; } else { revertedDonate = false; }

        assert(!revertedSecond && !revertedDonate);
    }

    receive() external payable {}
}

